const fs = require('fs');
const path = require('path');
const root = path.resolve(__dirname, '../..');
const read = (p) => fs.readFileSync(path.join(root,p),'utf8');
const onboarding = read('assets/js/core/onboarding.js');
const css = read('assets/css/core/onboarding.css');
const layout = read('assets/js/core/layout.js');
const api = read('functions/surveyor-api/src/main.js');
const home = read('index.html');
const map = read('mapa/index.html');
const assert = (cond,msg) => { if(!cond) throw new Error(msg); };
assert(onboarding.includes('REVIEW_AFTER_DAYS = 30'),'revisão de 30 dias ausente');
assert(onboarding.includes('ONBOARDING_ROLLOUT_AT'),'migração de contas antigas ausente');
assert(onboarding.includes("global: 1, mapa: 1, memorial: 1"),'versionamento de tours ausente');
assert(onboarding.includes("title: 'Mapa e Cadastro'"),'tour do mapa ausente');
assert(onboarding.includes("title: 'Memorial Descritivo'"),'tour do memorial ausente');
assert(onboarding.includes("title: 'Suporte'"),'tour de suporte ausente');
assert(onboarding.includes("title: 'Módulo CAR'"),'tour do módulo CAR ausente');
assert(!onboarding.includes("title: 'Cards da Página Inicial'"),'tour legado de cards do admin não deve existir na R16');
assert(onboarding.includes("const isHome = document.body?.dataset?.page === 'index.html'"),'botão de ajuda não está restrito à Home');
assert(onboarding.includes('Refazer introdução ao Surveyor'),'atalho da Home para refazer introdução ausente');
assert(!onboarding.includes('Refazer tutorial desta página'),'atalho flutuante de módulos ainda está presente');
assert(onboarding.includes("auth.apiFetch('/api/onboarding'"),'sincronização remota ausente');
assert(onboarding.includes("else if (key && tourNeeded(key))"),'tour contextual ainda depende indevidamente do tour global');
assert(onboarding.includes("page === 'suporte.html'"),'roteamento do tour de suporte ausente');
assert(onboarding.includes("page === 'car.html'"),'roteamento do tour CAR ausente');
assert(css.includes('.sv-tour-spotlight'),'spotlight CSS ausente');
assert(css.includes('@keyframes svTourPulse'),'animação de foco ausente');
assert(css.includes('left:7px;bottom:7px'),'botão de ajuda não está no canto solicitado');
assert(css.includes('width:29px;height:29px'),'botão de ajuda não foi reduzido');
assert(layout.includes('loadOnboardingAssets()'),'loader de onboarding ausente');
assert(layout.includes('/assets/js/core/onboarding.js'),'script de onboarding não carregado');
assert(layout.includes('onboarding-v3-0823'),'cache-bust do onboarding não atualizado');
assert(api.includes("path === '/api/onboarding' && httpMethod === 'GET'"),'GET /api/onboarding ausente');
assert(api.includes("path === '/api/onboarding' && ['PUT', 'POST', 'PATCH'].includes(httpMethod)"),'PATCH /api/onboarding ausente');
assert(api.includes('sanitizeOnboardingState'),'sanitização de onboarding ausente');
assert(api.includes('onboarding: sanitizeOnboardingState'),'novos usuários não inicializam onboarding na conta');
assert(home.includes('layout.js?v=21.11.5-onboarding-v3-0823'),'cache-bust da home não atualizado');
assert(map.includes('/assets/js/core/onboarding.js?v=21.11.5-onboarding-v3-0823'),'Mapa não carrega o motor de onboarding');
assert(map.includes('/assets/css/core/onboarding.css?v=21.11.5-onboarding-v3-0823'),'Mapa não carrega o CSS de onboarding');
console.log('OK onboarding: conta nova + Mapa + módulos + ajuda somente na Home.');
